import { useEffect, useRef, useState } from "react";

const BOTTOM_THRESHOLD = 24;
const SETTLE_TIMEOUT = 700;

export function useChatThreadScroll() {
  const viewportRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const pinnedRef = useRef(true);
  const [atBottom, setAtBottom] = useState(true);
  const settlingRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  function scrollToBottom(behavior: ScrollBehavior = "smooth") {
    const viewport = viewportRef.current;
    if (!viewport) return;
    pinnedRef.current = true;
    setAtBottom(true);
    clearTimeout(settlingRef.current);
    settlingRef.current = setTimeout(() => {
      settlingRef.current = undefined;
    }, SETTLE_TIMEOUT);
    viewport.scrollTo({ top: viewport.scrollHeight, behavior });
  }

  useEffect(() => {
    const viewport = viewportRef.current;
    const content = contentRef.current;
    if (!viewport || !content) return;

    function settle() {
      clearTimeout(settlingRef.current);
      settlingRef.current = undefined;
      readPosition();
    }

    function readPosition() {
      if (!viewport || settlingRef.current) return;
      const distance = viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight;
      pinnedRef.current = distance <= BOTTOM_THRESHOLD;
      setAtBottom(pinnedRef.current);
    }

    const observer = new ResizeObserver(() => {
      if (!viewport) return;
      if (pinnedRef.current) viewport.scrollTop = viewport.scrollHeight;
      else readPosition();
    });
    observer.observe(content);
    observer.observe(viewport);
    viewport.addEventListener("scroll", readPosition, { passive: true });
    viewport.addEventListener("scrollend", settle);
    viewport.scrollTop = viewport.scrollHeight;
    readPosition();

    return () => {
      observer.disconnect();
      clearTimeout(settlingRef.current);
      viewport.removeEventListener("scroll", readPosition);
      viewport.removeEventListener("scrollend", settle);
    };
  }, []);

  return { viewportRef, contentRef, atBottom, scrollToBottom };
}

// Generated from src/registry/sources/control-ui/recipes/chat-layout.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const chatLayoutKnobs = [
  "--cui-chat-layout-radius",
  "--cui-chat-layout-background",
  "--cui-chat-layout-border-color",
  "--cui-chat-layout-border-width",
  "--cui-chat-layout-shadow",
  "--cui-chat-layout-scroll-button-gap",
] as const;
export type ChatLayoutKnobStyle = Partial<Record<(typeof chatLayoutKnobs)[number], string>>;

"use client";

import { ArrowDown } from "lucide-react";
import type { ComponentProps, CSSProperties, MouseEvent, ReactNode } from "react";
import { createContext, useContext } from "react";
import { useChatThreadScroll } from "@/components/control-ui/hooks/use-chat-thread-scroll";
import type { ChatLayoutKnobStyle } from "@/components/control-ui/knob-contracts/chat-layout-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { SkinAdornment } from "@/components/control-ui/skin-provider";
import { Button } from "@/components/control-ui/ui/button";

export type ChatLayoutChrome = "panel" | "embedded";

export type ChatLayoutProps = Omit<ComponentProps<"section">, "style"> & {
  chrome?: ChatLayoutChrome;
  style?: CSSProperties & ChatLayoutKnobStyle;
};

const chromeSizing: Record<ChatLayoutChrome, string> = {
  panel: "mx-auto min-h-[640px] max-w-3xl",
  embedded: "h-full min-h-0 flex-1",
};

export function ChatLayout({ children, chrome = "panel", className, ...props }: ChatLayoutProps) {
  return (
    <section
      data-control-ui="chat-layout"
      data-control-family="chat-layout"
      data-slot="root"
      data-chrome={chrome}
      data-surface={chrome === "panel" ? "panel" : undefined}
      className={cn("relative flex w-full flex-col overflow-hidden", chromeSizing[chrome], className)}
      {...props}
    >
      {chrome === "panel" ? <SkinAdornment scope="chat-layout" part="titlebar" context={{}} /> : null}
      {children}
    </section>
  );
}

type ChatThreadScrollContextValue = {
  atBottom: boolean;
  scrollToBottom: (behavior?: ScrollBehavior) => void;
};

const ChatThreadScrollContext = createContext<ChatThreadScrollContextValue | null>(null);

export type ChatThreadProps = ComponentProps<"div"> & {
  composer?: ReactNode;
};

export function ChatThread({ children, composer, className, ...props }: ChatThreadProps) {
  const { viewportRef, contentRef, atBottom, scrollToBottom } = useChatThreadScroll();

  return (
    <ChatThreadScrollContext.Provider value={{ atBottom, scrollToBottom }}>
      <div
        ref={viewportRef}
        data-control-ui="chat-thread"
        data-control-family="chat-layout"
        data-chat-layout-kind="thread"
        data-slot="root"
        data-at-bottom={atBottom ? "" : undefined}
        className={cn("min-h-0 min-w-0 flex-1 overflow-y-auto", className)}
        {...props}
      >
        <div ref={contentRef} className="relative flex min-h-full min-w-0 flex-col">
          <div
            data-control-ui="chat-thread"
            data-control-family="chat-layout"
            data-slot="thread-content"
            className="flex min-w-0 flex-1 flex-col"
          >
            {children}
          </div>
          {composer ? (
            <div data-control-ui="chat-thread" data-control-family="chat-layout" data-slot="dock" className="sticky bottom-0 z-10 shrink-0">
              {composer}
            </div>
          ) : null}
        </div>
      </div>
    </ChatThreadScrollContext.Provider>
  );
}

export type ChatThreadScrollButtonProps = Omit<ComponentProps<typeof Button>, "children"> & {
  label?: string;
};

export function ChatThreadScrollButton({ label = "Scroll to latest", className, onClick, ...props }: ChatThreadScrollButtonProps) {
  const scroll = useContext(ChatThreadScrollContext);
  if (!scroll) throw new Error("<ChatThreadScrollButton> must be rendered inside <ChatThread>.");

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    if (!event.defaultPrevented) scroll?.scrollToBottom();
  }

  return (
    <div
      data-control-ui="chat-thread"
      data-control-family="chat-layout"
      data-slot="scroll-anchor"
      data-hidden={scroll.atBottom ? "" : undefined}
    >
      <Button
        {...props}
        type="button"
        variant="surface"
        size="sm"
        iconOnly
        aria-label={label}
        onClick={handleClick}
        className={cn("rounded-full", className)}
      >
        <ArrowDown aria-hidden="true" />
      </Button>
    </div>
  );
}

export type ChatTurnProps = ComponentProps<"section"> & {
  from: "user" | "assistant";
};

export function ChatTurn({ from, children, className, ...props }: ChatTurnProps) {
  return (
    <section
      data-control-ui="chat-turn"
      data-control-family="chat-layout"
      data-slot="turn"
      data-from={from}
      className={cn("flex w-full flex-col", from === "user" && "items-end", className)}
      {...props}
    >
      {children}
    </section>
  );
}

@layer components {
  :where([data-control-family="chat-layout"][data-slot="root"][data-chrome]) {
    --cui-chat-layout-radius: var(--radius-scene);
    --cui-chat-layout-background: var(--background);
    --cui-chat-layout-border-color: var(--border);
    --cui-chat-layout-border-width: var(--control-rim-width);
    --cui-chat-layout-shadow: var(--shadow-md);
    --cui-chat-layout-scroll-button-gap: calc(var(--spacing) * 3);
    background: var(--cui-chat-layout-background);
  }

  :where([data-control-family="chat-layout"][data-slot="root"][data-chrome="panel"]) {
    border: var(--cui-chat-layout-border-width) solid var(--cui-chat-layout-border-color);
    border-radius: var(--cui-chat-layout-radius);
    box-shadow: var(--cui-chat-layout-shadow);
  }

  :where([data-control-family="chat-layout"][data-slot="thread-content"]) {
    gap: calc(var(--spacing) * 8);
    padding-block: calc(var(--spacing) * 6);
    padding-inline: calc(var(--spacing) * 4);
  }

  @media (width >= 40rem) {
    :where([data-control-family="chat-layout"][data-slot="thread-content"]) {
      padding-inline: calc(var(--spacing) * 8);
    }
  }

  :where([data-control-family="chat-layout"][data-slot="dock"])::before {
    content: "";
    position: absolute;
    inset: calc(var(--scroll-fade-size) * -1) 0 0;
    z-index: -1;
    pointer-events: none;
    background: var(--cui-chat-layout-background);
    mask-image: linear-gradient(to bottom, transparent, oklch(0 0 0 / 0.7) calc(var(--scroll-fade-size) * 3));
  }

  :where([data-control-family="chat-layout"][data-slot="scroll-anchor"]) {
    position: absolute;
    inset-block-end: calc(100% + var(--cui-chat-layout-scroll-button-gap));
    inset-inline: 0;
    margin-inline: auto;
    inline-size: fit-content;
    transition-property: opacity, scale, visibility;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="chat-layout"][data-slot="scroll-anchor"][data-hidden]) {
    opacity: 0;
    scale: 0.9;
    visibility: hidden;
  }
}

@property --cui-chat-layout-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-chat-layout-scroll-button-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}
